/// The least code point that is not a starter or whose quick check for NFC is not Yes.
/// Text made only of code points below it is its own normalization in that form.
pub(crate) const NFC_TRIVIAL_LIMIT: char = '\u{0300}';

/// The least code point that is not a starter or whose quick check for NFD is not Yes.
/// Text made only of code points below it is its own normalization in that form.
pub(crate) const NFD_TRIVIAL_LIMIT: char = '\u{00C0}';

/// The least code point that is not a starter or whose quick check for NFKC is not Yes.
/// Text made only of code points below it is its own normalization in that form.
pub(crate) const NFKC_TRIVIAL_LIMIT: char = '\u{00A0}';

/// The least code point that is not a starter or whose quick check for NFKD is not Yes.
/// Text made only of code points below it is its own normalization in that form.
pub(crate) const NFKD_TRIVIAL_LIMIT: char = '\u{00A0}';

/// The most code points one code point decomposes into fully, in any form: the room a
/// decomposition is written into.
pub(crate) const LONGEST_DECOMPOSITION: usize = 18;

/// The most marks one starter composes with, one after another, in a composing form: of the
/// marks held after a starter, no more than this many are gone from the answer.
pub(crate) const MOST_MARKS_COMPOSED: usize = 3;
